begin;

-- Career launch: Gmail iOS dark mode — remove color-scheme meta (was fighting client), add gradient + @media header guard
update public.email_templates
set
  html_template = $crl129_html$<!DOCTYPE html><html><head><meta charset="utf-8"/><meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><style type="text/css">.crl-top-header,.crl-top-header table,.crl-top-header td{background:#0B0F19!important;background-color:#0B0F19!important;background-image:linear-gradient(#0B0F19,#0B0F19)!important;color:#FFFFFF!important;-webkit-text-fill-color:#FFFFFF!important}@media (prefers-color-scheme:dark){.crl-top-header,.crl-top-header table,.crl-top-header td{background:#0B0F19!important;background-color:#0B0F19!important;color:#FFFFFF!important;-webkit-text-fill-color:#FFFFFF!important}}</style><title>Welcome to {{program_name}}</title></head><body style="margin:0;padding:0;background-color:#F8FAFC;font-family:Arial,Helvetica,sans-serif;color:#111827;-webkit-text-size-adjust:100%;"><div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:transparent;opacity:0;">{{email_preheader_text}}</div><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#F8FAFC" style="background-color:#F8FAFC;mso-table-lspace:0;mso-table-rspace:0;"><tr><td align="center" style="padding:24px 12px;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#ffffff" style="max-width:680px;background-color:#ffffff;border:1px solid #E5E7EB;border-radius:10px;mso-table-lspace:0;mso-table-rspace:0;"><tr><td class="crl-top-header" bgcolor="#0B0F19" style="background:linear-gradient(#0B0F19,#0B0F19);background-color:#0B0F19;border-bottom:2px solid #F59E0B;padding:22px 24px;"><table class="crl-top-header" role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#0B0F19" style="background:linear-gradient(#0B0F19,#0B0F19);background-color:#0B0F19;mso-table-lspace:0;mso-table-rspace:0;"><tr><td width="52" valign="middle" bgcolor="#0B0F19" style="background:linear-gradient(#0B0F19,#0B0F19);background-color:#0B0F19;padding:0;vertical-align:middle;"><img src="{{email_logo_url}}" width="48" height="48" alt="NextGen CTO Logo" style="width:48px;height:auto;display:block;border:0;outline:none;text-decoration:none;"/></td><td valign="middle" bgcolor="#0B0F19" style="background:linear-gradient(#0B0F19,#0B0F19);background-color:#0B0F19;color:#FFFFFF;-webkit-text-fill-color:#FFFFFF;font-size:18px;font-weight:800;padding-left:12px;vertical-align:middle;">{{email_header_display}}</td></tr></table></td></tr><tr><td bgcolor="#ffffff" style="background-color:#FFFFFF;padding:20px 22px 24px 22px;"><p style="margin:0 0 8px 0;font-size:12px;font-weight:700;color:#F59E0B;text-transform:uppercase;letter-spacing:0.08em;">Program Launch</p><h1 style="margin:0 0 10px 0;font-size:26px;line-height:1.25;color:#0F172A;font-weight:800;">Welcome to {{program_name}}</h1><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="margin:0 0 18px 0;"><tr><td height="2" bgcolor="#F59E0B" style="background-color:#F59E0B;font-size:0;line-height:0;">&nbsp;</td></tr></table><p style="margin:0 0 14px 0;font-size:15px;line-height:1.7;color:#334155;">Hi <strong>{{first_name}}</strong>,</p><table role="presentation" cellspacing="0" cellpadding="0" border="0" style="margin:22px 0 26px 0;"><tr><td align="left"><a href="{{cta_url}}" style="display:inline-block;background:linear-gradient(135deg,#e58c33 0%,#d97a1f 100%);color:#FFFFFF;text-decoration:none;font-family:Arial,Helvetica,sans-serif;font-size:16px;font-weight:700;padding:14px 22px;border-radius:50px;box-shadow:0 6px 20px rgba(229,140,51,0.35);letter-spacing:0.5px;">{{cta_label}}</a></td></tr></table><p style="margin:0 0 12px 0;font-size:15px;line-height:1.7;color:#334155;">{{email_program_lead_html}}</p><p style="margin:0 0 6px 0;font-size:15px;line-height:1.7;color:#334155;">This is not just another course.</p><p style="margin:0 0 14px 0;font-size:15px;line-height:1.7;color:#334155;">It is designed to help you build the things that actually matter when you start preparing for internships, interviews, and your first serious career opportunities:</p><ul style="margin:0 0 18px 0;padding-left:18px;"><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Strong technical foundations</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Hands-on project experience</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">GitHub, Resume, and LinkedIn readiness</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">AI-powered development exposure</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Interview and communication confidence</li><li style="margin:0;font-size:14px;line-height:1.6;color:#334155;">Mentorship and community support</li></ul><p style="margin:0 0 8px 0;font-size:15px;font-weight:700;color:#0F172A;">Why this matters</p><p style="margin:0 0 8px 0;font-size:15px;line-height:1.7;color:#334155;">Most students learn randomly.</p><p style="margin:0 0 8px 0;font-size:15px;line-height:1.7;color:#334155;">One day DSA. One day web development. One day AI tools. One day resume building.</p><p style="margin:0 0 8px 0;font-size:15px;line-height:1.7;color:#334155;">But without a clear path, learning becomes confusing.</p><p style="margin:0 0 18px 0;font-size:15px;line-height:1.7;color:#334155;">{{program_name}} gives you a structured roadmap so you know what to learn, what to build, and how to present your work professionally.</p><p style="margin:0 0 8px 0;font-size:15px;font-weight:700;color:#0F172A;">What you will work on</p><ol style="margin:0 0 18px 0;padding-left:18px;"><li style="margin:0 0 10px 0;font-size:14px;line-height:1.6;color:#334155;"><strong>Build your technical base.</strong> Strengthen programming fundamentals, problem-solving thinking, web basics, backend concepts, APIs, databases, Git, and GitHub.</li><li style="margin:0 0 10px 0;font-size:14px;line-height:1.6;color:#334155;"><strong>Explore modern AI-powered development.</strong> Learn how AI-assisted coding, prompt basics, generative AI, agentic AI concepts, and simple automation workflows fit into modern software development.</li><li style="margin:0 0 10px 0;font-size:14px;line-height:1.6;color:#334155;"><strong>Create project proof.</strong> Work on portfolio-building and real-world application practice so your learning is visible, not hidden inside notebooks or theory.</li><li style="margin:0 0 10px 0;font-size:14px;line-height:1.6;color:#334155;"><strong>Improve your career profile.</strong> Start building a stronger Resume, GitHub profile, and LinkedIn presence so you look more prepared when opportunities come.</li><li style="margin:0;font-size:14px;line-height:1.6;color:#334155;"><strong>Prepare for interviews with confidence.</strong> Improve communication, structured thinking, interview mindset, and practical readiness with mentorship and guided support.</li></ol><p style="margin:0 0 8px 0;font-size:15px;font-weight:700;color:#0F172A;">What you should aim for</p><p style="margin:0 0 10px 0;font-size:15px;line-height:1.7;color:#334155;">By the end of this journey, you should be able to show visible progress:</p><ul style="margin:0 0 18px 0;padding-left:18px;"><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">A stronger understanding of technical concepts</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">A GitHub profile with meaningful project work</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">A more complete Resume + LinkedIn profile</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Better confidence in interviews and communication</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Exposure to AI-driven development workflows</li><li style="margin:0;font-size:14px;line-height:1.6;color:#334155;">A clear eligibility path for the NextGen CTO Academy Industry Ready Certificate</li></ul><p style="margin:0 0 8px 0;font-size:15px;font-weight:700;color:#0F172A;">Your first step</p><p style="margin:0 0 6px 0;font-size:15px;line-height:1.7;color:#334155;">Open your dashboard, explore the roadmap, and start with the first recommended module.</p><p style="margin:0 0 6px 0;font-size:15px;line-height:1.7;color:#334155;">Do not wait for the perfect time.</p><p style="margin:0 0 16px 0;font-size:15px;line-height:1.7;color:#334155;">Start small. Stay consistent. Build visible proof.</p><p style="margin:0 0 6px 0;font-size:15px;font-weight:700;color:#0F172A;">Need help during the journey?</p><p style="margin:0 0 8px 0;font-size:15px;line-height:1.7;color:#334155;">You are not expected to figure everything out alone. Use the support and community channels whenever you feel stuck.</p><p style="margin:0 0 8px 0;font-size:13px;color:#5A3D1A;">Support: <a href="{{support_url}}" style="color:#F4A854;text-decoration:none;font-weight:600;">{{support_url}}</a></p></td></tr><tr><td align="center" bgcolor="#ffffff" style="text-align:center;margin-top:50px;font-size:0.9em;color:#777;padding:25px 20px;background:#ffffff;background-color:#ffffff;"><table role="presentation" cellspacing="0" cellpadding="0" border="0" align="center" style="margin:0 auto;"><tr><td valign="middle" style="padding-right:10px;"><img src="{{email_logo_url}}" alt="NextGen CTO" width="56" style="display:block;border:0;outline:none;text-decoration:none;height:auto;"/></td><td valign="middle" style="font-family:Arial,Helvetica,sans-serif;font-size:18px;font-weight:700;line-height:1.2;color:#1E335C;">NextGen CTO</td></tr></table><div style="margin:auto;text-align:center;"><p style="color:#172B4D;font-size:14px;font-weight:600;">Follow us on</p><table role="presentation" cellspacing="0" cellpadding="0" border="0" align="center" style="margin:0 auto;"><tr><td style="padding:0 6px;"><a href="https://www.instagram.com/code.with.ctobhaiya?igsh=MTgyM3ZyY2V6enJheQ==" style="cursor:pointer;text-decoration:none;"><img src="https://algozenith.s3.ap-south-1.amazonaws.com/content/07-06-24/8059_a58afaf2-29b8-4761-9c0e-6d9fc6ae6f4a.png" style="width:40px;height:40px;" alt="Instagram"/></a></td><td style="padding:0 6px;"><a href="https://www.linkedin.com/in/anuj-kumar-a-k-a-cto-bhaiya-on-youtube-9a188968/" style="cursor:pointer;text-decoration:none;"><img src="https://algozenith.s3.ap-south-1.amazonaws.com/content/07-06-24/8059_44a6715c-441d-43f8-b5ee-bad637d717d3.png" style="width:40px;height:40px;" alt="LinkedIn"/></a></td><td style="padding:0 6px;"><a href="https://www.youtube.com/@CodingwithCTOBhaiya" style="cursor:pointer;text-decoration:none;"><img src="https://algozenith.s3.ap-south-1.amazonaws.com/content/07-06-24/8059_11a31c49-ba39-442b-81ac-b0816e2a71a1.png" style="width:40px;height:40px;" alt="YouTube"/></a></td></tr></table></div><div style="flex-grow:1;height:1px;background-color:black;margin-top:2rem;"></div><p style="font-weight:300;margin:0;padding:0;text-align:center;font-size:15px;">If you are no longer interested, click <a href="{{unsubscribe_url}}">here</a> to unsubscribe.</p><p style="font-weight:300;margin-top:6px;text-align:center;font-size:15px;">© Copyright 2025. NextGen CTO Pvt Ltd. All Rights Reserved.</p></td></tr></table></td></tr></table></body></html>$crl129_html$,
  updated_at = now()
where slug = 'career-readiness-program-launch';

